/* Adapter only; neural-network computation is generated by STM32Cube.AI. */
#include <stdint.h>
#include "b2_decoder.h"
#include "b2_mingru.h"
#include "b2_mingru_data.h"
#include "b2_packed_weights.h"

_Static_assert(AI_B2_MINGRU_IN_NUM == 10, "Expected window plus nine fixed weight inputs");
_Static_assert(AI_B2_MINGRU_IN_1_SIZE == 192 * 50, "Input shape changed");
_Static_assert(AI_B2_MINGRU_OUT_1_SIZE == 2, "Output shape changed");

static ai_handle network = AI_HANDLE_NULL;

size_t b2_decoder_activation_bytes(void) {
    return AI_B2_MINGRU_DATA_ACTIVATIONS_SIZE;
}

int b2_decoder_init(void *activation_buffer, size_t buffer_bytes) {
    if (network != AI_HANDLE_NULL) return -1;
    if (!activation_buffer || buffer_bytes < b2_decoder_activation_bytes() ||
        ((uintptr_t)activation_buffer % AI_B2_MINGRU_ACTIVATIONS_ALIGNMENT) != 0) return -2;
    const ai_handle activations[] = { activation_buffer };
    ai_error err = ai_b2_mingru_create_and_init(&network, activations, NULL);
    if (err.type != AI_ERROR_NONE) {
        if (network != AI_HANDLE_NULL) ai_b2_mingru_destroy(network);
        network = AI_HANDLE_NULL;
        return -3;
    }
    return 0;
}

int b2_decoder_run(const float *normalized_window, float *normalized_velocity) {
    if (network == AI_HANDLE_NULL || !normalized_window || !normalized_velocity) return -1;
    ai_u16 n_inputs = 0, n_outputs = 0;
    ai_buffer *inputs = ai_b2_mingru_inputs_get(network, &n_inputs);
    ai_buffer *outputs = ai_b2_mingru_outputs_get(network, &n_outputs);
    if (!inputs || !outputs || n_inputs != 10 || n_outputs != 1) return -2;
    inputs[0].data = (ai_handle)normalized_window;
    for (unsigned i = 0; i < B2_PACKED_WEIGHT_COUNT; ++i) {
        inputs[i + 1].data = (ai_handle)b2_packed_weights[i];
    }
    outputs[0].data = (ai_handle)normalized_velocity;
    return ai_b2_mingru_run(network, inputs, outputs) == 1 ? 0 : -3;
}

void b2_decoder_destroy(void) {
    if (network != AI_HANDLE_NULL) ai_b2_mingru_destroy(network);
    network = AI_HANDLE_NULL;
}
